(5283263, 769372, 36981, '<td valign="top">S/he is stunning!  What a beautiful capture of a beautiful animal.</td>', 'S/he is stunning!  What a beautiful capture of a beautiful animal.', '2009-03-02 10:00:00.000000', NULL, 1),
(5283264, 768386, 36981, '<td valign="top">This is a very beautiful image; one of my favorites.</td>', 'This is a very beautiful image; one of my favorites.', '2009-03-02 10:00:21.000000', NULL, 1),
(5283265, 769445, 37719, '<td valign="top">Not sure this is the kind of ''light'' that was intended.</td>', 'Not sure this is the kind of ''light'' that was intended.', '2009-03-02 10:00:35.000000', NULL, 1),
(5283267, 769486, 36981, '<td valign="top">It''s great fun to see an action shot in this challenge!  Really well done &amp; a fun photo to boot.</td>', 'It''s great fun to see an action shot in this challenge!  Really well done & a fun photo to boot.', '2009-03-02 10:00:55.000000', NULL, 1),
(5283269, 768256, 100064, '<td valign="top">Very creative!  I would have dodged out that yellow cast above the headlights and some of the rest of the background could use a little more work in dodging but its really cool!</td>', 'Very creative!  I would have dodged out that yellow cast above the headlights and some of the rest of the background could use a little more work in dodging but its really cool!', '2009-03-02 10:01:10.000000', NULL, 1),
(5283272, 769250, 100064, '<td valign="top">I expected to see pictures like this but this one is really nice and stands above a lot of the rest.  The greens are beautiful and very nice detail. Crisp looking. I really like that the vase is broken to. Nice!</td>', 'I expected to see pictures like this but this one is really nice and stands above a lot of the rest.  The greens are beautiful and very nice detail. Crisp looking. I really like that the vase is broken to. Nice!', '2009-03-02 10:02:06.000000', NULL, 1),
(5283277, 769436, 74979, '<td valign="top">great image really, but I dont see BLACK pumps as a light colored subject..</td>', 'great image really, but I dont see BLACK pumps as a light colored subject..', '2009-03-02 10:04:23.000000', NULL, 1),
(5283279, 769473, 57447, '<td valign="top">This fits the challenge so well.</td>', 'This fits the challenge so well.', '2009-03-02 10:05:52.000000', NULL, 1),
