INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5283375, 769017, 68467, '<td valign="top">He he very creative - 7</td>', 'He he very creative - 7', '2009-03-02 10:41:31.000000', NULL, 1),
(5283377, 769529, 68467, '<td valign="top">Brown</td>', 'Brown', '2009-03-02 10:42:30.000000', NULL, 1),
(5283379, 768910, 68467, '<td valign="top">stunning - this flower is allways nice to shoot - 7</td>', 'stunning - this flower is allways nice to shoot - 7', '2009-03-02 10:45:11.000000', NULL, 1),
(5283380, 769471, 76585, '<td valign="top">nice shot 10</td>', 'nice shot 10', '2009-03-02 10:45:28.000000', NULL, 1),
(5283384, 769489, 68467, '<td valign="top">very delicate and well exposed</td>', 'very delicate and well exposed', '2009-03-02 10:47:12.000000', NULL, 1),
(5283386, 769519, 68467, '<td valign="top">Brown I guess</td>', 'Brown I guess', '2009-03-02 10:48:28.000000', NULL, 1),
(5283387, 769510, 68467, '<td valign="top">Brown</td>', 'Brown', '2009-03-02 10:48:31.000000', NULL, 1),
(5283390, 769588, 74979, '<td valign="top">pretty flowers...background seems a tad too white (almost blown out, if that makes ANY sense?)</td>', 'pretty flowers...background seems a tad too white (almost blown out, if that makes ANY sense?)', '2009-03-02 10:53:42.000000', NULL, 1),
(5283396, 769351, 43774, '<td valign="top">I love this!!! That bit of red  anchors the shot.</td>', 'I love this!!! That bit of red  anchors the shot.', '2009-03-02 10:55:46.000000', NULL, 1),
(5283399, 768766, 98141, '<td valign="top">The dark clothing and necklace make this dnmc to me... "Take a photo in which the background is white and the subject is predominately a lighter color." I suppose that the skin is technically a predominately lighter color, but I think the darkness of the other colors take away from the idea of the challenge.</td>', 'The dark clothing and necklace make this dnmc to me... "Take a photo in which the background is white and the subject is predominately a lighter color." I suppose that the skin is technically a predominately lighter color, but I think the darkness of the other colors take away from the idea of the challenge.', '2009-03-02 10:56:58.000000', NULL, 1),
(5283401, 769319, 98141, '<td valign="top">I think if this were slightly overexposed it would do better in this challenge. Having their skin look more like porcelin and less sun-familiar just would have made it fit better with the challenge description, imho.</td>', 'I think if this were slightly overexposed it would do better in this challenge. Having their skin look more like porcelin and less sun-familiar just would have made it fit better with the challenge description, imho.', '2009-03-02 10:58:23.000000', NULL, 1),
(5283404, 769465, 98141, '<td valign="top">This is interesting, something about it feels off, ... I think without as many shadows (behind the egg, behind the cubes) and with different composition (try putting the egg somewhere other than the center of the pic) it would have done better.</td>', 'This is interesting, something about it feels off, ... I think without as many shadows (behind the egg, behind the cubes) and with different composition (try putting the egg somewhere other than the center of the pic) it would have done better.', '2009-03-02 10:59:56.000000', NULL, 1),
(5283409, 768905, 98141, '<td valign="top">Overall, I think that if the exposure would have been higher, I think this would have scored better. I also don''t think it''s that appealing of a subject by itself. But, I think it would be more appealing, at least for this challenge, if it were higher key.</td>', 'Overall, I think that if the exposure would have been higher, I think this would have scored better. I also don''t think it''s that appealing of a subject by itself. But, I think it would be more appealing, at least for this challenge, if it were higher key.', '2009-03-02 11:01:40.000000', NULL, 1),
(5283415, 769596, 98141, '<td valign="top">I think this is too dark to do well in this challenge... If the smoke/steam were lighter (really white) and the building were white, then I think it would fit better.</td>', 'I think this is too dark to do well in this challenge... If the smoke/steam were lighter (really white) and the building were white, then I think it would fit better.', '2009-03-02 11:04:12.000000', NULL, 1),
(5283420, 769373, 98141, '<td valign="top">I think this could be a lot sharper, it feels grainy to me. I also find the shadow distracting.</td>', 'I think this could be a lot sharper, it feels grainy to me. I also find the shadow distracting.', '2009-03-02 11:05:28.000000', NULL, 1),
(5283424, 769510, 98141, '<td valign="top">I don''t really care for the pp on this... I think perhaps she has too much dark hair to be a perfect candidate for this challenge.</td>', 'I don''t really care for the pp on this... I think perhaps she has too much dark hair to be a perfect candidate for this challenge.', '2009-03-02 11:06:36.000000', NULL, 1),
(5283428, 769201, 98141, '<td valign="top">I think this is beautiful. Great lighting , great positioning, great composition.</td>', 'I think this is beautiful. Great lighting , great positioning, great composition.', '2009-03-02 11:07:42.000000', NULL, 1),
(5283432, 769487, 98141, '<td valign="top">Man do those eyes pop perfectly or what? Great clarity and great tones, you did very well with the lighting.</td>', 'Man do those eyes pop perfectly or what? Great clarity and great tones, you did very well with the lighting.', '2009-03-02 11:08:23.000000', NULL, 1),
(5283437, 767647, 98141, '<td valign="top">This is a pic that I like, but I don''t think that it really meets the challenge''s criteria. I actually really like the colors of the windmill and the treeline - the dark colors. Unless you made the fence your subject - and it doesn''t feel like the subject here at all to me - with snow as your background, this doesn''t fit.</td>', 'This is a pic that I like, but I don''t think that it really meets the challenge''s criteria. I actually really like the colors of the windmill and the treeline - the dark colors. Unless you made the fence your subject - and it doesn''t feel like the subject here at all to me - with snow as your background, this doesn''t fit.', '2009-03-02 11:11:18.000000', NULL, 1),
(5283442, 769590, 98141, '<td valign="top">I like this a lot and I feel that it shows a lot of attitude/character. Good pet portrait, nice dof, definitely fits the challenge.</td>', 'I like this a lot and I feel that it shows a lot of attitude/character. Good pet portrait, nice dof, definitely fits the challenge.', '2009-03-02 11:13:05.000000', NULL, 1),
(5283451, 768934, 98141, '<td valign="top">I like the idea for this a lot. Something about it feels a little off or messy to me though - I think perhaps if it were a little bit sharper it would have a stronger impact. I also think that the tulle is a bit distracting, that perhaps with just legs and not the skirt it would be stronger.</td>', 'I like the idea for this a lot. Something about it feels a little off or messy to me though - I think perhaps if it were a little bit sharper it would have a stronger impact. I also think that the tulle is a bit distracting, that perhaps with just legs and not the skirt it would be stronger.', '2009-03-02 11:19:25.000000', NULL, 1),
(5283454, 769482, 98141, '<td valign="top">I have to say I don''t really care for this. I think the dof is too shallow. I think it would be better for this challenge if you only used the white ones.</td>', 'I have to say I don''t really care for this. I think the dof is too shallow. I think it would be better for this challenge if you only used the white ones.', '2009-03-02 11:20:45.000000', NULL, 1),
(5283456, 769382, 98141, '<td valign="top">I like this, but there feels like a lot of grey going on in a light on white challenge. I guess perhaps I''m just being too picky, but I am just trying to explain what my first impression is. The flower is so starkly white, it just kind of renders the rest of the pic as grey tones to me.</td>', 'I like this, but there feels like a lot of grey going on in a light on white challenge. I guess perhaps I''m just being too picky, but I am just trying to explain what my first impression is. The flower is so starkly white, it just kind of renders the rest of the pic as grey tones to me.', '2009-03-02 11:21:43.000000', NULL, 1),
(5283460, 769257, 98141, '<td valign="top">I''m not sure what I feel is missing here. I like the composition. I think perhaps lighter lips in blak and white would look really nice and soft.</td>', 'I''m not sure what I feel is missing here. I like the composition. I think perhaps lighter lips in blak and white would look really nice and soft.', '2009-03-02 11:22:42.000000', NULL, 1),
(5283469, 768879, 98141, '<td valign="top">Cutie pie! But this feels too much like a snapshot for me. I think perhaps if the eyes were sharper and the nose were slightly oof, so that there''s more of a feeling of depth that might fix it up nicely. The eyes look really uneven to me. One looks so shiny and one looks really cloudy. Maybe that''s the way it really is, but it almost feels like editing or something.</td>', 'Cutie pie! But this feels too much like a snapshot for me. I think perhaps if the eyes were sharper and the nose were slightly oof, so that there''s more of a feeling of depth that might fix it up nicely. The eyes look really uneven to me. One looks so shiny and one looks really cloudy. Maybe that''s the way it really is, but it almost feels like editing or something.', '2009-03-02 11:24:25.000000', NULL, 1),
(5283472, 769516, 98141, '<td valign="top">I like this. I think the darkness in the shot is just limited enough to pop rather than take over the image. Great composition.</td>', 'I like this. I think the darkness in the shot is just limited enough to pop rather than take over the image. Great composition.', '2009-03-02 11:25:05.000000', NULL, 1),
(5283475, 768840, 98141, '<td valign="top">I really like the composition for this. It feels like it could be a lot sharper, and I think if it were it would really stand out.</td>', 'I really like the composition for this. It feels like it could be a lot sharper, and I think if it were it would really stand out.', '2009-03-02 11:25:56.000000', NULL, 1),
(5283481, 769555, 98141, '<td valign="top">Haha, I love the title and I think this works really well for the challenge. Normally I''m not a fan of shadows like that, but I think it helps to define the shape of the subject here.</td>', 'Haha, I love the title and I think this works really well for the challenge. Normally I''m not a fan of shadows like that, but I think it helps to define the shape of the subject here.', '2009-03-02 11:27:29.000000', NULL, 1),
(5283494, 769299, 103792, '<td valign="top">Cute concept.  I just find the top of the photo to be way too bright.</td>', 'Cute concept.  I just find the top of the photo to be way too bright.', '2009-03-02 11:30:58.000000', NULL, 1),
(5283497, 768741, 103792, '<td valign="top">Think it may be a little better if all three were in focus.</td>', 'Think it may be a little better if all three were in focus.', '2009-03-02 11:31:46.000000', NULL, 1),
(5283498, 768740, 104427, '<td valign="top">Gorgeous - a classic High Key image...</td>', 'Gorgeous - a classic High Key image...', '2009-03-02 11:31:57.000000', NULL, 1),
(5283500, 768433, 103792, '<td valign="top">Very good photo but it looses some with the shrubbery in the bottom right corner.</td>', 'Very good photo but it looses some with the shrubbery in the bottom right corner.', '2009-03-02 11:32:45.000000', NULL, 1),
(5283503, 769255, 103792, '<td valign="top">More like camouflage!</td>', 'More like camouflage!', '2009-03-02 11:33:40.000000', NULL, 1),
(5283507, 768844, 98141, '<td valign="top">I love that at first glance, this just seems to be the label and the cap floating in air. Then, as I let it sit there the bottle and words started to appear. It''s like a Magic Eye game or something. I think the exposure is spot-on.</td>', 'I love that at first glance, this just seems to be the label and the cap floating in air. Then, as I let it sit there the bottle and words started to appear. It''s like a Magic Eye game or something. I think the exposure is spot-on.', '2009-03-02 11:34:38.000000', NULL, 1),
(5283509, 768699, 104427, '<td valign="top">Beautiful - classic High Key image. I would have preferred a slightly narrower and mid-grey border, though - this one is a little dominant in my humble opinion.</td>', 'Beautiful - classic High Key image. I would have preferred a slightly narrower and mid-grey border, though - this one is a little dominant in my humble opinion.', '2009-03-02 11:34:38.000000', NULL, 1),
(5283510, 769296, 103792, '<td valign="top">Too many shells blurred in the background.  Feel that it looses it''s "on white" concept.</td>', 'Too many shells blurred in the background.  Feel that it looses it''s "on white" concept.', '2009-03-02 11:34:49.000000', NULL, 1),
(5283511, 769467, 104427, '<td valign="top">Love the patterns...</td>', 'Love the patterns...', '2009-03-02 11:35:39.000000', NULL, 1),
(5283513, 768767, 103792, '<td valign="top">Cute...just feels that there''s too much background light coming in.</td>', 'Cute...just feels that there''s too much background light coming in.', '2009-03-02 11:35:54.000000', NULL, 1),
(5283515, 769486, 98141, '<td valign="top">This is cute, but it feels like cut and paste to me. I feel like it''s another picture of people jumping that was cut and paste onto a background of white. I don''t know why that matters, but for some reason it makes the pic feel fake to me.</td>', 'This is cute, but it feels like cut and paste to me. I feel like it''s another picture of people jumping that was cut and paste onto a background of white. I don''t know why that matters, but for some reason it makes the pic feel fake to me.', '2009-03-02 11:36:21.000000', NULL, 1),
(5283517, 768058, 104427, '<td valign="top">Excellent! Perfect subject and very well captured. This deserves to do very well.</td>', 'Excellent! Perfect subject and very well captured. This deserves to do very well.', '2009-03-02 11:36:27.000000', NULL, 1),
(5283519, 768850, 95579, '<td valign="top">Superbly light on white!</td>', 'Superbly light on white!', '2009-03-02 11:37:10.000000', NULL, 1),
(5283520, 769486, 104427, '<td valign="top">Fabulous image...</td>', 'Fabulous image...', '2009-03-02 11:37:11.000000', NULL, 1),
(5283521, 768895, 98141, '<td valign="top">If there wasn''t such a strong shadow in the background I think this would do better in this challenge. I think that well-lit subjects are going to do better, and that shadow definitely makes the background feel un-white.</td>', 'If there wasn''t such a strong shadow in the background I think this would do better in this challenge. I think that well-lit subjects are going to do better, and that shadow definitely makes the background feel un-white.', '2009-03-02 11:37:29.000000', NULL, 1),
(5283522, 769367, 103792, '<td valign="top">Too many dark spots and I would have liked the fish more in focus.</td>', 'Too many dark spots and I would have liked the fish more in focus.', '2009-03-02 11:37:45.000000', NULL, 1),
(5283525, 769504, 98141, '<td valign="top">Lovely. Great details and texture in the petals and stem. I think the green pops and that the colors and teh exposure fit the challenge nicely.</td>', 'Lovely. Great details and texture in the petals and stem. I think the green pops and that the colors and teh exposure fit the challenge nicely.', '2009-03-02 11:38:09.000000', NULL, 1),
(5283528, 769409, 104427, '<td valign="top">Good composition - great depth. And I love the subtle colours.</td>', 'Good composition - great depth. And I love the subtle colours.', '2009-03-02 11:38:28.000000', NULL, 1),
(5283532, 769130, 98141, '<td valign="top">Beautiful dog! I think that if the dof were less inclusive and the impuities on the snow behind it weren''t so visible the effect here would be stronger.</td>', 'Beautiful dog! I think that if the dof were less inclusive and the impuities on the snow behind it weren''t so visible the effect here would be stronger.', '2009-03-02 11:39:18.000000', NULL, 1),
(5283533, 769294, 104427, '<td valign="top">Very creative...</td>', 'Very creative...', '2009-03-02 11:39:32.000000', NULL, 1),
(5283535, 769435, 104427, '<td valign="top">So elegant...I love the lighting!</td>', 'So elegant...I love the lighting!', '2009-03-02 11:40:27.000000', NULL, 1),
(5283537, 769549, 98141, '<td valign="top">Hahaha, I get it. Neat idea. It feels like it might be compression, but I find this a little blotchy...</td>', 'Hahaha, I get it. Neat idea. It feels like it might be compression, but I find this a little blotchy...', '2009-03-02 11:41:03.000000', NULL, 1),
(5283539, 769478, 104427, '<td valign="top">A beautiful image, but I wouldn''t have thought it was ''light'' enough for this contest.</td>', 'A beautiful image, but I wouldn''t have thought it was ''light'' enough for this contest.', '2009-03-02 11:41:21.000000', NULL, 1),
(5283540, 768637, 95579, '<td valign="top">interesting line, very minimalistic, good shot</td>', 'interesting line, very minimalistic, good shot', '2009-03-02 11:41:39.000000', NULL, 1),
(5283542, 769428, 104427, '<td valign="top">Simple and elegant - very effective.</td>', 'Simple and elegant - very effective.', '2009-03-02 11:41:53.000000', NULL, 1),
(5283544, 769470, 95579, '<td valign="top">Love the white on white</td>', 'Love the white on white', '2009-03-02 11:42:10.000000', NULL, 1),
(5283545, 769547, 98141, '<td valign="top">I''m having trouble figuring out what that''s made out of. My first impressions was that it was bread. It''s an interesting idea and I''m certain that it will be the only one of its kind in this challenge. Feels a little fuzzy and I don''t care for the shadows where it touches the bottom surface.</td>', 'I''m having trouble figuring out what that''s made out of. My first impressions was that it was bread. It''s an interesting idea and I''m certain that it will be the only one of its kind in this challenge. Feels a little fuzzy and I don''t care for the shadows where it touches the bottom surface.', '2009-03-02 11:42:37.000000', NULL, 1),
(5283546, 769523, 104427, '<td valign="top">Love the crop and the clarity.</td>', 'Love the crop and the clarity.', '2009-03-02 11:43:05.000000', NULL, 1),
(5283549, 769296, 95579, '<td valign="top">I thought it was chocoltae at first!  I think I would like a bigger dof, but its all about personal taste</td>', 'I thought it was chocoltae at first!  I think I would like a bigger dof, but its all about personal taste', '2009-03-02 11:43:44.000000', NULL, 1),
(5283552, 768637, 98141, '<td valign="top">This is a cool pick. I like the composition and the way the red pops but it doesn''t take over the pic. I think it would have an even stronger effect if it didn''t have shadows. More even lighting from both sides might change that.</td>', 'This is a cool pick. I like the composition and the way the red pops but it doesn''t take over the pic. I think it would have an even stronger effect if it didn''t have shadows. More even lighting from both sides might change that.', '2009-03-02 11:43:52.000000', NULL, 1),
(5283554, 767784, 104427, '<td valign="top">Great use of light and form - would make an excellent print.</td>', 'Great use of light and form - would make an excellent print.', '2009-03-02 11:44:03.000000', NULL, 1),
(5283558, 768699, 98141, '<td valign="top">I like this but I really don''t care for the thick black border around a pic in a light on white challenge. I think it takes away from the pic a lot.</td>', 'I like this but I really don''t care for the thick black border around a pic in a light on white challenge. I think it takes away from the pic a lot.', '2009-03-02 11:44:34.000000', NULL, 1),
(5283559, 768058, 95579, '<td valign="top">Lovely, well shot to keep the definition in the ice. Slight gradient on the background but it still looks white as far as im concerned : )</td>', 'Lovely, well shot to keep the definition in the ice. Slight gradient on the background but it still looks white as far as im concerned : )', '2009-03-02 11:44:50.000000', NULL, 1),
(5283560, 768664, 98141, '<td valign="top">To me this does not meet the challenge criteria. "Take a photo in which the background is white and the subject is predominately a lighter color." The background here does not look white to me, and the subject is certainly not a lighter color. I think it has cool composition but could be sharper.</td>', 'To me this does not meet the challenge criteria. "Take a photo in which the background is white and the subject is predominately a lighter color." The background here does not look white to me, and the subject is certainly not a lighter color. I think it has cool composition but could be sharper.', '2009-03-02 11:45:03.000000', NULL, 1),
(5283561, 768910, 104427, '<td valign="top">-That''s nice - lovely placement of the flower centre.</td>', '-That''s nice - lovely placement of the flower centre.', '2009-03-02 11:45:07.000000', NULL, 1),
(5283563, 768981, 95579, '<td valign="top">Interesting angle</td>', 'Interesting angle', '2009-03-02 11:45:24.000000', NULL, 1),
(5283567, 769546, 98141, '<td valign="top">I wish this were sharper. It''s a little dull to be honest, I think a macro of her face or a different composition could pump some attitude and life into this. Good subject for the challenge though.</td>', 'I wish this were sharper. It''s a little dull to be honest, I think a macro of her face or a different composition could pump some attitude and life into this. Good subject for the challenge though.', '2009-03-02 11:45:54.000000', NULL, 1),
(5283568, 769079, 98141, '<td valign="top">I LOVE this. I love the sparse, black tips of their wings and I love the dof and I love the randomness of their placement and I love that the ones are the bottom are a little cut off - it makes me feel like this is a pattern that could go on forever. Really well done.</td>', 'I LOVE this. I love the sparse, black tips of their wings and I love the dof and I love the randomness of their placement and I love that the ones are the bottom are a little cut off - it makes me feel like this is a pattern that could go on forever. Really well done.', '2009-03-02 11:45:57.000000', NULL, 1),
(5283569, 768669, 98141, '<td valign="top">To me, this does not meet the challenge... "Take a photo in which the background is white and the subject is predominately a lighter color." I suppose the background is white if your subject is the person''s face, but all the darkness in the picture takes away from that.</td>', 'To me, this does not meet the challenge... "Take a photo in which the background is white and the subject is predominately a lighter color." I suppose the background is white if your subject is the person''s face, but all the darkness in the picture takes away from that.', '2009-03-02 11:46:04.000000', NULL, 1),
(5283570, 769372, 95579, '<td valign="top">Wow!!  Absolutely lovely shot. Yes theres a bit of grey in the background so it isnt pure white but who cares!! not me thats for sure</td>', 'Wow!!  Absolutely lovely shot. Yes theres a bit of grey in the background so it isnt pure white but who cares!! not me thats for sure', '2009-03-02 11:46:12.000000', NULL, 1),
(5283571, 769372, 104427, '<td valign="top">Beautiful image - such concentration.</td>', 'Beautiful image - such concentration.', '2009-03-02 11:46:16.000000', NULL, 1),
(5283575, 769301, 98141, '<td valign="top">This is beautiful. The yellow pops and the stem is so soft and the lighting and exposure on the petals is perfect. Great dof as well. Just lovely.</td>', 'This is beautiful. The yellow pops and the stem is so soft and the lighting and exposure on the petals is perfect. Great dof as well. Just lovely.', '2009-03-02 11:46:51.000000', NULL, 1),
(5283579, 769558, 104427, '<td valign="top">Great positioning in the frame. How nice to have two of them coming for a look...</td>', 'Great positioning in the frame. How nice to have two of them coming for a look...', '2009-03-02 11:47:23.000000', NULL, 1),
(5283593, 769555, 104427, '<td valign="top">Great detail and lovely lighting - I would like a poster of that in my kitchen...</td>', 'Great detail and lovely lighting - I would like a poster of that in my kitchen...', '2009-03-02 11:49:49.000000', NULL, 1),
(5283595, 768935, 98141, '<td valign="top">I''ve been looking at this for a while. It definitely meets the challenge, so no problems there. The thing that I notice the most other than the subject is the darker corner in the upper right. I also think the subject isn''t quite sharp enough or perhaps it is just slightly too overexposed. I can''t really put my finger on it, but there is a quality in this photo that keeps it from being great, but prevents it from being bad.</td>', 'I''ve been looking at this for a while. It definitely meets the challenge, so no problems there. The thing that I notice the most other than the subject is the darker corner in the upper right. I also think the subject isn''t quite sharp enough or perhaps it is just slightly too overexposed. I can''t really put my finger on it, but there is a quality in this photo that keeps it from being great, but prevents it from being bad.', '2009-03-02 11:50:40.000000', NULL, 1),
(5283597, 769328, 103792, '<td valign="top">Would be better if you used a white background.</td>', 'Would be better if you used a white background.', '2009-03-02 11:50:45.000000', NULL, 1),
(5283599, 769489, 95579, '<td valign="top">I like the feet in the fishnets &amp; the chairleg and the bottom of the skirt. The top of the skirt where it is blown out is a little too bright for me, maybe I would have trimmed the top 1/2 inch off. but thats me not you so pinch of salt :)<br/>Overall a pleasing image</td>', 'I like the feet in the fishnets & the chairleg and the bottom of the skirt. The top of the skirt where it is blown out is a little too bright for me, maybe I would have trimmed the top 1/2 inch off. but thats me not you so pinch of salt :)Overall a pleasing image', '2009-03-02 11:50:56.000000', NULL, 1),
