(5294970, 769372, 43774, '<td valign="top">Wow, powerful gaze, nice.</td>', 'Wow, powerful gaze, nice.', '2009-03-07 22:29:39.000000', NULL, 1),
(5294971, 769540, 43774, '<td valign="top">A beautiful dog, nicely done.</td>', 'A beautiful dog, nicely done.', '2009-03-07 22:29:40.000000', NULL, 1),
(5294972, 769267, 43774, '<td valign="top">Clever! Well done, nice and clear, good colour in the pear.</td>', 'Clever! Well done, nice and clear, good colour in the pear.', '2009-03-07 22:29:41.000000', NULL, 1),
(5294973, 768058, 43774, '<td valign="top">Very clear, interesting photo.</td>', 'Very clear, interesting photo.', '2009-03-07 22:29:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5294974, 769380, 43774, '<td valign="top">This must be Irene''s photo! Love the detail in the feather.</td>', 'This must be Irene''s photo! Love the detail in the feather.', '2009-03-07 22:29:49.000000', NULL, 1),
(5294975, 769504, 43774, '<td valign="top">Love the angle you shot this from.</td>', 'Love the angle you shot this from.', '2009-03-07 22:29:50.000000', NULL, 1),
(5294976, 769604, 43774, '<td valign="top">This looks like very good stock photography. Very clear, good composition.</td>', 'This looks like very good stock photography. Very clear, good composition.', '2009-03-07 22:29:51.000000', NULL, 1),
(5294977, 768980, 43774, '<td valign="top">Really nice product shot, well done.</td>', 'Really nice product shot, well done.', '2009-03-07 22:29:52.000000', NULL, 1),
(5294978, 768448, 43774, '<td valign="top">Very clear, good detail. Composition doesn''t seem perfect, maybe if the feather were more on an angle it would look better.</td>', 'Very clear, good detail. Composition doesn''t seem perfect, maybe if the feather were more on an angle it would look better.', '2009-03-07 22:29:53.000000', NULL, 1),
(5294979, 769523, 43774, '<td valign="top">Very clear, nice close crop, good job.</td>', 'Very clear, nice close crop, good job.', '2009-03-07 22:29:58.000000', NULL, 1),
(5294980, 768532, 43774, '<td valign="top">Clarity and DOF are perfect. Could almost be an ad except for the fact that the bracelet seems a bit uneven/bent.</td>', 'Clarity and DOF are perfect. Could almost be an ad except for the fact that the bracelet seems a bit uneven/bent.', '2009-03-07 22:30:01.000000', NULL, 1),
(5294982, 769011, 43774, '<td valign="top">She looks sleepy. :) Lovely photo.</td>', 'She looks sleepy. :) Lovely photo.', '2009-03-07 22:30:06.000000', NULL, 1),
(5295169, 769607, 96915, '<td valign="top">The white seems to have a blue cast.  Composition and subject are not very engaging to me.</td>', 'The white seems to have a blue cast.  Composition and subject are not very engaging to me.', '2009-03-07 23:45:40.000000', NULL, 1),
(5295171, 768669, 96915, '<td valign="top">I''m not really seeing the light on white.  It''s late, so I''ll not vote now and come back to it.<br/> <br/>So I''m back and the white I''m assuming to be whitewater, but I''m still feeling like this is a stretch of the challenge.</td>', 'I''m not really seeing the light on white.  It''s late, so I''ll not vote now and come back to it. So I''m back and the white I''m assuming to be whitewater, but I''m still feeling like this is a stretch of the challenge.', '2009-03-07 23:47:44.000000', NULL, 1),
(5295173, 769488, 96915, '<td valign="top">I''m not real fond of the processing here, but aside from that, this is nice, I like the variations of white in the flower.</td>', 'I''m not real fond of the processing here, but aside from that, this is nice, I like the variations of white in the flower.', '2009-03-07 23:48:34.000000', NULL, 1),
(5295403, 768314, 100393, '<td valign="top">I think the post processing is too harsh - all the more jarring because of the delicacy of the subject.</td>', 'I think the post processing is too harsh - all the more jarring because of the delicacy of the subject.', '2009-03-08 04:16:41.000000', NULL, 1),
(5295518, 769351, 47852, '<td valign="top">The variety of shape and texture in the pasta is great, and the little hint of color adds a perfect finishing touch.  Well done!</td>', 'The variety of shape and texture in the pasta is great, and the little hint of color adds a perfect finishing touch.  Well done!', '2009-03-08 08:50:47.000000', NULL, 1),
(5295520, 768433, 47852, '<td valign="top">What a cutie!  The little bits of color really help to make this guy stand out, but the white fur stands out just enough on its own.  Wonder what happened to the little guys ear!  Great job!</td>', 'What a cutie!  The little bits of color really help to make this guy stand out, but the white fur stands out just enough on its own.  Wonder what happened to the little guys ear!  Great job!', '2009-03-08 08:52:14.000000', NULL, 1),
(5295522, 769380, 47852, '<td valign="top">Love the lines created in the white background, they help to give something extra to the composition. I wish the feather was a bit more pastel to really keep with the light on white theme, but the color works nicely for the overall photo.</td>', 'Love the lines created in the white background, they help to give something extra to the composition. I wish the feather was a bit more pastel to really keep with the light on white theme, but the color works nicely for the overall photo.', '2009-03-08 08:53:51.000000', NULL, 1),
(5295523, 769429, 47852, '<td valign="top">Love the shallow dof here, and the way the back petals blend in to the whiteness.  The fact that the stem is covered with the whites works very nicely for this shot too.  I''m not sure about the composition, I think I might have preferred the petals to be a diagonal between the two corners without cutting off the edge of the petals on the left.  Wonderful job!</td>', 'Love the shallow dof here, and the way the back petals blend in to the whiteness.  The fact that the stem is covered with the whites works very nicely for this shot too.  I''m not sure about the composition, I think I might have preferred the petals to be a diagonal between the two corners without cutting off the edge of the petals on the left.  Wonderful job!', '2009-03-08 08:56:03.000000', NULL, 1),
(5295524, 768740, 47852, '<td valign="top">Perfect subject for the challenge.  That back foot looks a bit awkward, but I love how the pink paws nose and ears as well as the green eyes stand out against the white.</td>', 'Perfect subject for the challenge.  That back foot looks a bit awkward, but I love how the pink paws nose and ears as well as the green eyes stand out against the white.', '2009-03-08 08:57:30.000000', NULL, 1),
(5295529, 769294, 47852, '<td valign="top">Love the flowing arrangement of the pages.  The shallow dof allows the text to just stand out enough to reinforce those flowing lines.  There seems to be some sort of banding in the background around the edges of the pages which would be the only thing I would try to fix with this shot.</td>', 'Love the flowing arrangement of the pages.  The shallow dof allows the text to just stand out enough to reinforce those flowing lines.  There seems to be some sort of banding in the background around the edges of the pages which would be the only thing I would try to fix with this shot.', '2009-03-08 09:02:18.000000', NULL, 1),
(5295593, 768714, 94815, '<td valign="top">Seems off topic. Darker colors dominate.</td>', 'Seems off topic. Darker colors dominate.', '2009-03-08 10:16:13.000000', NULL, 1),
(5295594, 769435, 53892, '<td valign="top">nice</td>', 'nice', '2009-03-08 10:16:20.000000', NULL, 1),
(5295596, 769367, 53892, '<td valign="top">bright</td>', 'bright', '2009-03-08 10:16:48.000000', NULL, 1),
(5295706, 769204, 3724, '<td valign="top">aka toon-kies</td>', 'aka toon-kies', '2009-03-08 11:42:51.000000', NULL, 1),
(5295716, 768256, 56502, '<td valign="top">The dress and model look somehow familiar ... Interesting setup!</td>', 'The dress and model look somehow familiar ... Interesting setup!', '2009-03-08 11:51:59.000000', NULL, 1),
(5295753, 769530, 104318, '<td valign="top">fine</td>', 'fine', '2009-03-08 12:21:06.000000', NULL, 1),
(5295845, 768664, 102315, '<td valign="top">The snow looks like water to me because of all the divots in it. Kinda throws the shot off a little and makes my eyes want to leave the subject too much.</td>', 'The snow looks like water to me because of all the divots in it. Kinda throws the shot off a little and makes my eyes want to leave the subject too much.', '2009-03-08 14:10:24.000000', NULL, 1),
(5295847, 769409, 102315, '<td valign="top">UUMmmmmm. I think this looks more delicious because of the white background.</td>', 'UUMmmmmm. I think this looks more delicious because of the white background.', '2009-03-08 14:11:34.000000', NULL, 1),
(5295850, 769151, 102315, '<td valign="top">Seems a bit out of focus. However, it looks like a difficult capture.</td>', 'Seems a bit out of focus. However, it looks like a difficult capture.', '2009-03-08 14:12:48.000000', NULL, 1),
(5295851, 769604, 102315, '<td valign="top">Nice focus</td>', 'Nice focus', '2009-03-08 14:13:13.000000', NULL, 1),
