(5295975, 769608, 102315, '<td valign="top">One of the few tens I have given so far in this challenge. A flower done right!</td>', 'One of the few tens I have given so far in this challenge. A flower done right!', '2009-03-08 15:06:12.000000', NULL, 1),
(5295976, 769504, 102315, '<td valign="top">Good twist on the flower shot. A shot from the back instead of the front. I like it.</td>', 'Good twist on the flower shot. A shot from the back instead of the front. I like it.', '2009-03-08 15:06:56.000000', NULL, 1),
